package com.catalogix.feature.service; import com.catalogix.feature.model.FeatureFlag; import com.catalogix.feature.repository.FeatureRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class FeatureService{final FeatureRepository repo;public FeatureService(FeatureRepository r){repo=r;}@Transactional(readOnly=true)public Map<String,Boolean> all(){Map<String,Boolean> out=new TreeMap<>();repo.findAll().forEach(f->out.put(f.getName(),f.isEnabled()));return out;}@Transactional public Map<String,Boolean> set(String name,boolean enabled){FeatureFlag f=repo.findByName(name).orElseGet(()->new FeatureFlag(name,enabled));f.setEnabled(enabled);repo.save(f);return all();}}
